/* ===========================================================================
   vault-og.js — animation d'ouverture du coffre-fort (Ober'Games)
   Fichier autonome : images incluses, Three.js chargé depuis un CDN au besoin.

   INTÉGRATION (dans index.html) :
     <script src="vault-og.js"></script>
     <script>
       VaultOG.preload();                  // facultatif : prépare l'animation en arrière-plan
       // Quand la connexion Supabase est VALIDÉE (à la place de l'ancienne animation) :
       await VaultOG.play({
         onCovered: () => {                // l'écran est entièrement sombre : change de page ici
           document.querySelector('#login').style.display = 'none';
           document.querySelector('#evenement').style.display = 'block';
         }
       });
     </script>
   Si WebGL ou le réseau pose problème, onCovered est appelé tout de suite (aucun blocage).
   ========================================================================== */
